#!/usr/bin/env node
/**
 * postbuild — host-agnostic extras written into dist/ after `astro build`:
 *   dist/_redirects  (Netlify & Cloudflare Pages format) from src/data/redirects.json
 *   dist/_headers    (Netlify & Cloudflare Pages) long-term caching for hashed assets,
 *                    security headers for HTML
 * Hosts that ignore these files (e.g. GitHub Pages) still get HTML redirect pages
 * generated by Astro's `redirects` config.
 */
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { DIST_DIR, loadData } from './lib/load-data.mjs';

const data = loadData();
const redirects = data.redirects.map((r) => `${r.from}  ${r.to}  ${r.status}`).join('\n');
writeFileSync(join(DIST_DIR, '_redirects'), `# Generated from src/data/redirects.json\n${redirects}\n`);

const headers = `# Generated by scripts/postbuild.mjs
/_astro/*
  Cache-Control: public, max-age=31536000, immutable
/fonts/*
  Cache-Control: public, max-age=31536000, immutable
/brand/*
  Cache-Control: public, max-age=604800
/*
  X-Content-Type-Options: nosniff
  Referrer-Policy: strict-origin-when-cross-origin
  Permissions-Policy: camera=(), microphone=(), geolocation=()
  X-Frame-Options: SAMEORIGIN
`;
writeFileSync(join(DIST_DIR, '_headers'), headers);
writeFileSync(join(DIST_DIR, '.nojekyll'), '');
console.log(`postbuild: _redirects (${data.redirects.length}), _headers, and .nojekyll written.`);
